/* =================================================================
   PETSHOP.LT — Brand UI Foundation
   Karkasas v1.3 + Mygtukų sistema v1.1
   Data: 2026-05-07 | Versija: 1.5
   ================================================================= */

/* === 1. OPEN SANS GLOBAL ENFORCEMENT === */
body,
input,
textarea,
select,
button,
.button {
  font-family: 'Open Sans', system-ui, -apple-system, sans-serif !important;
}
body {
  font-weight: 400;
}
h1, h2 {
  font-family: 'Open Sans', system-ui, sans-serif !important;
  font-weight: 700 !important;
  color: #2a2a2a;
}
h3, h4, h5, h6 {
  font-family: 'Open Sans', system-ui, sans-serif !important;
  font-weight: 600 !important;
  color: #2a2a2a;
}
.nav &gt; li &gt; a,
.header-nav a,
.nav-dropdown a {
  font-weight: 600 !important;
}
.button,
button,
input[type="submit"],
.add_to_cart_button,
.single_add_to_cart_button,
.checkout-button {
  font-weight: 600 !important;
}
.price,
.woocommerce-Price-amount.amount {
  font-weight: 700;
}

/* === 2. PAGE BACKGROUND === */
body {
  background-color: #f4f4f2;
}

/* === 3. PRIMARY BUTTONS === */
.add_to_cart_button,
.single_add_to_cart_button,
.button.primary,
.checkout-button,
button[type="submit"] {
  background-color: #365a51 !important;
  color: #ffffff !important;
  border: 1.5px solid #365a51 !important;
  border-radius: 4px;
  transition: all 0.15s ease;
}
.add_to_cart_button:hover,
.single_add_to_cart_button:hover,
.button.primary:hover,
.checkout-button:hover,
button[type="submit"]:hover {
  background-color: #2a4640 !important;
  border-color: #2a4640 !important;
  color: #ffffff !important;
}

/* === 4. SALE BADGE === */
span.onsale,
.onsale {
  background-color: #c47b5d !important;
  color: #ffffff !important;
  font-weight: 700 !important;
  border-radius: 4px !important;
  border: none !important;
  padding: 3px 8px !important;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  font-size: 11px;
}

/* === 5. STRIKETHROUGH PRICE === */
del .woocommerce-Price-amount,
del .amount {
  color: #888780 !important;
  font-weight: 400 !important;
}

/* === 6. DISABLED STATES === */
button:disabled,
.button.disabled,
.button[disabled] {
  background-color: #b0c2bc !important;
  color: #fffcec !important;
  border-color: #b0c2bc !important;
  cursor: not-allowed !important;
  opacity: 1 !important;
}

/* === 7. SMOOTH TRANSITIONS === */
a {
  transition: color 0.15s ease;
}
.button:active,
button:active {
  transform: scale(0.98);
}

/* === 8. MEGA MENU — Brand UI Foundation v1.3 === */

/* Dropdown padding */
.nav-dropdown {
  padding-top: 28px !important;
  padding-bottom: 28px !important;
}

/* Grupavimo antraštės — bold, uppercase, žalia, neklikamos */
.nav-dropdown a[href="#"] {
  font-family: 'Open Sans', system-ui, sans-serif !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  text-transform: uppercase !important;
  color: #365a51 !important;
  letter-spacing: 0 !important;
  pointer-events: none !important;
  cursor: default !important;
}

/* Subkategorijų tekstas */
.nav-dropdown li:not(.menu-item-has-children) &gt; a {
  font-size: 15px !important;
  font-weight: 400 !important;
  line-height: 1.35 !important;
  color: #5f5e5a !important;
}

/* Hover */
.nav-dropdown li:not(.menu-item-has-children) &gt; a:hover {
  color: #365a51 !important;
}

/* Separatoriai — subtilūs */
.nav-dropdown .menu-item &gt; a {
  border-bottom-color: #e5e7e0 !important;
}
/* === 9. NAV JUOSTA — fonas pagal brand karkasą === */
.header-bottom,
.nav-bar,
.header-nav-wrap {
  background-color: #f4f4f2 !important;
  border-top: 1px solid #e5e7e0 !important;
  border-bottom: 1px solid #e5e7e0 !important;
}
.cart_totals .shop_table tr.shipping th,
.cart_totals .shop_table tr.shipping td {
    vertical-align: top;
    width: 50%;
}
#top-bar {
    font-size: 18px;
}
.woocommerce-tabs .wc-tab h2,
.woocommerce .shop_attributes,
ul.wc-tabs li.reviews_tab a {
    /* placeholder */
	}
/* ===== S71 — nuolaidos badge: apvalus, ant nuotraukos, oranzinis ===== */

.products .product-small.col {
    position: relative;
}
.products .product-small .col-inner {
    position: static;
}

/* Badge — apvalus, pastumtas ant nuotraukos zonos */
.products .product-small .badge-container {
    position: absolute !important;
    top: 12px !important;
    left: 12px !important;
    right: auto !important;
    bottom: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    width: 50px !important;
    height: 50px !important;
    z-index: 20;
}

.products .product-small .badge-container .callout,
.products .product-small .badge-container .badge,
.products .product-small .badge-container .badge-inner,
.products .product-small .badge-container span {
    width: 50px !important;
    height: 50px !important;
    border-radius: 50% !important;
    background-color: #ff6b35 !important;
    color: #ffffff !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-weight: 700 !important;
    font-size: 13px !important;
    line-height: 1 !important;
    padding: 0 !important;
    margin: 0 !important;
}
/* ============================================================
   PETSHOP.LT — Katalogo nuotrauku suvienodinimas v7
   Flatsome: .box-image &gt; .image-fade_in_back &gt; a &gt; img
   v9 (savininko pageidavimas):
     - out-of-stock nuotrauka LABIAU isblukusi (opacity 0.45 + grayscale 55%)
       kad klientas iskart matytu, jog prekes nera
   v6/v5: image box 1/1.15, padding 2px, 4/3/2, vienodi title blokai
   Nieko nekerpama (object-fit: contain), baltas fonas.
   ============================================================ */

/* --- 1. Image box: siek tiek aukstesnis nei kvadratas --- */
.products li.product .box-image,
.products .product-small .box-image {
	position: relative;
	width: 100%;
	aspect-ratio: 1 / 1.15;
	background: #fff;
	overflow: hidden;
}

.products li.product .box-image .image-fade_in_back,
.products li.product .box-image .image-fade_in_back &gt; a,
.products .product-small .box-image .image-fade_in_back,
.products .product-small .box-image .image-fade_in_back &gt; a {
	display: block;
	width: 100%;
	height: 100%;
}

.products li.product .box-image img,
.products .product-small .box-image img {
	width: 100% !important;
	height: 100% !important;
	object-fit: contain !important;
	object-position: center !important;
	padding: 2px;
	box-sizing: border-box;
	background: #fff;
}

/* --- 2. 4/3/2 prekes i eile --- */
@media (min-width: 850px) {
	.products .product-small.col,
	ul.products li.product {
		width: 25% !important;
		max-width: 25% !important;
		flex: 0 0 25% !important;
	}
}
@media (min-width: 550px) and (max-width: 849px) {
	.products .product-small.col,
	ul.products li.product {
		width: 33.3333% !important;
		max-width: 33.3333% !important;
		flex: 0 0 33.3333% !important;
	}
}

/* --- 3. Mazesni vertikalus tarpai --- */
.products .product-small.col,
ul.products li.product {
	margin-bottom: 0 !important;
	padding-bottom: 10px !important;
}
.products .box-image {
	margin-bottom: 6px !important;
}
.products .box-text {
	padding-top: 2px !important;
}

/* --- 4. Vienodas pavadinimo bloko aukstis --- */
.products .box-text .title-wrapper {
	min-height: 16px;
}
.products .box-text .name.product-title,
.products .box-text p.name {
	min-height: 3.6em;
	overflow: hidden;
	display: -webkit-box;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
	line-height: 1.2;
	margin-bottom: 6px;
}

/* --- 5. "Neturime" badge: svelnus, sviesiai pilkas, virsuje DESINEJE --- */
.products li.product .box-image .out-of-stock-label,
.product-small .box-image .out-of-stock-label {
	position: absolute !important;
	top: 10px !important;
	right: 10px !important;
	left: auto !important;
	bottom: auto !important;
	transform: none !important;
	margin: 0 !important;
	width: auto !important;
	max-width: calc(100% - 16px) !important;
	padding: 4px 9px !important;
	font-size: 11px !important;
	font-weight: 600 !important;
	line-height: 1.3 !important;
	text-transform: none !important;        /* "Neturime", ne "NETURIME" */
	letter-spacing: 0.2px !important;
	color: #555 !important;
	background: #f2f2f2 !important;
	border: 1px solid #e2e2e2 !important;
	border-radius: 14px !important;          /* svelniai apvalus */
	z-index: 6 !important;
	white-space: nowrap !important;
	box-shadow: 0 1px 2px rgba(0,0,0,0.06) !important;
}

/* --- 6. Out-of-stock nuotrauka: blankesne (subtilu, preke matosi) --- */
.products li.product.outofstock .box-image img,
.products li.product.out-of-stock .box-image img,
.product-small.outofstock .box-image img,
.product-small.out-of-stock .box-image img {
	opacity: 0.45 !important;
	filter: grayscale(55%) !important;
}
/* S1709: isparduotai prekei antros (hover) nuotraukos nerodyti - kitaip opacity 0.45 ja padaro matoma ir abi nuotraukos persidengia */
.products li.product.outofstock .box-image img.back-image,
.products li.product.out-of-stock .box-image img.back-image,
.product-small.outofstock .box-image img.back-image,
.product-small.out-of-stock .box-image img.back-image {
	display: none !important;
}
